    verdict: 'unjudged', verdictNote: '**2026-09-03 Pencilを直したので未判定に戻した。** 横断レビュー §7 の反映：#31 サイドメニューの選択状態／#40 主ボタンの緑を `$accent-deep` へ（白文字 2.26:1 → 5.44:1）／#44 CSV書き出しの置き場／#48 表記統一。設計画像を撮り直した。**実装との突き合わせはこれから。** **#574 `0906b8fa` で4状態を撮った。前に挙げたP1（状態の言い分けが設計とそろわない）は、一覧の中身については解消した。** ルート `/inflow-links?tab=links`。通常・読込・0件・取得失敗を1440・1920で撮った（計8枚、**すべて横スクロール0**）。 **① 一覧の中身は3つが別の文になった。** 読込＝「流入リンクを読み込んでいます／このまま少しお待ちください。」、失敗＝「**流入リンクを表示できませんでした／登録したリンクは消えていません。**状態を読み直して、もう一度お試しください。」＋「**再読み込み**」、0件＝フォルダごとに0を出す。**失敗のときに「登録したリンクは消えていません。」と言うのは束1の手本。** **② 取得失敗のとき帯は0ではなく `—`。** 流入元 `—件`／今月の追加 `—人`／クリック `—回`／平均の追加率 `—%` で、4つとも「取得できませんでした」。0件のときは 流入元 `0件`（稼働中0）／クリック `0回`（累計）と**数えて0で出す**ので、**未取得と実値0が見分けられる**。 **③ 取得失敗のとき「最初のフォルダを作る」の誘導を出さない**（数えて0件）。 **④ `API error` `Failed to fetch` `undefined` `NaN` `Invalid Date` 内部IDは4状態とも0件。** **P2 読込中の帯が「取得できませんでした」と出る。** 読込と失敗で**帯の文が同じ**（どちらも `—` ＋「取得できませんでした」）。一覧の中身は「読み込んでいます」と正しく分かれているのに、**帯だけが読み込み中を失敗として書く**。短い時間だが、遅い回線では失敗と読み違える。**推奨修正**：帯にも読込の状態を渡し、「読み込んでいます」に切り替える。`RW5Tb`（リッチメニュー・#577）が同じ帯で読込と失敗を言い分けているので、その形を写す。 **P2 「今月の追加」は通常でも `—人`／「前月比は出せません」。** これは集計の口が無いためで、**正しい断り**。 取得元：`inflow-v6/BMmxU-normal.txt` ＋ `-loading` `-empty` `-error`', verdictSource: 'inflow-v6/BMmxU-loading.txt + BMmxU-error.txt',
